func findSemanticDescriptor*(
    jsonPointer: string
): Option[SemanticDescriptor] =
  ## Looks up the correction for an exact OpenAPI JSON Pointer.
  for descriptor in semanticDescriptors:
    if descriptor.jsonPointer == jsonPointer:
      return some(descriptor)
  none(SemanticDescriptor)

func semanticDescriptorsForSchema*(
    schemaName: string
): seq[SemanticDescriptor] =
  ## Returns all corrections attached to a component schema.
  for descriptor in semanticDescriptors:
    if descriptor.schemaName == schemaName:
      result.add descriptor

func semanticDescriptorsForProperty*(
    schemaName, propertyName: string
): seq[SemanticDescriptor] =
  ## Returns corrections attached to a named schema property.
  for descriptor in semanticDescriptors:
    if descriptor.schemaName == schemaName and
        descriptor.propertyName == propertyName:
      result.add descriptor
